public (int vowels, int consonants) CountVowelsAndConsonants(string word)
{
    int vowels = 0;
    int consonants = 0;

    foreach (var ch in word)
    {
        if (!char.IsLetter(ch))
            continue;

        char lower = char.ToLowerInvariant(ch);

        if (lower == 'a' || lower == 'e' || lower == 'i' || lower == 'o' || lower == 'u')
            vowels++;
        else
            consonants++;
    }

    return (vowels, consonants);
}

